#!/usr/bin/env python3
from pathlib import Path
import base64,gzip,hashlib,json,sys
src=Path(sys.argv[1]).resolve();ev=Path(sys.argv[2]).resolve();ev.mkdir(parents=True,exist_ok=True)
root=src/"SP/code/rend2"
sha=lambda b:hashlib.sha256(b).hexdigest()
elss=root/"tr_elss.inc"; electric=root/"tr_electric_fixture.inc"; local=root/"tr_local.h"; backend=root/"tr_backend.c"
assert sha(elss.read_bytes())=="fb680b71233ca6346507819e46c4ae9e06cd3b3d7fb91b6d235c5394e6df7130",sha(elss.read_bytes())
assert sha(electric.read_bytes())=="077b6210160254830dd5ad1f3c0c00c9df23391640660093b2cfe20edaab8c0d",sha(electric.read_bytes())
bs=backend.read_text()
assert "FIREVOL_CLEAN_PRODUCTION" in bs and "DARKWOLF_FIREVOL_CRYPT1_SLOT6_REANCHOR_PRODUCTION" in bs
old=elss.read_text()
assert old.index("R_ELSS_UpsertOwner") < old.index("R_ELSS_PrepareProfileFixture",old.index("void R_ELSS_Frame"))
module=gzip.decompress(base64.b64decode(""""""))
assert sha(module)=="4ab48f2ba8ac9484140ab9e2da486f1248e6c176a2a0341dc88989d857d23325"
elss.write_bytes(module)

s=local.read_text()
oldproto="qboolean R_ELSS_SuppressManualDrawSurf(const drawSurf_t *ds,int fixture,unsigned int key);"
assert s.count(oldproto)==1
s=s.replace(oldproto,oldproto+"\nconst unsigned char *R_ELSS_ManualOmitMask(const drawSurf_t *ds,int fixture,unsigned int key,int *triangleCount);")
local.write_text(s)

s=electric.read_text()
oldbranch='''    if(fixture<0) {
        if ((backEnd.viewParms.flags & (VPF_SHADOWMAP|VPF_DEPTHSHADOW)) == (VPF_SHADOWMAP|VPF_DEPTHSHADOW) &&
            !(backEnd.viewParms.flags & (VPF_ORTHOGRAPHIC|VPF_FIREVOL_SYNTHETIC_SHADOW)) &&
            R_ELSS_SuppressManualDrawSurf(ds,fixture,backEnd.viewParms.electricFixtureKey)) return;
        goto original;
    }
'''
newbranch='''    if(fixture<0) {
        if ((backEnd.viewParms.flags & (VPF_SHADOWMAP|VPF_DEPTHSHADOW)) == (VPF_SHADOWMAP|VPF_DEPTHSHADOW) &&
            !(backEnd.viewParms.flags & (VPF_ORTHOGRAPHIC|VPF_FIREVOL_SYNTHETIC_SHADOW))) {
            int triangleCount=0;
            const unsigned char *omit;
            if (R_ELSS_SuppressManualDrawSurf(ds,fixture,backEnd.viewParms.electricFixtureKey)) return;
            omit=R_ELSS_ManualOmitMask(ds,fixture,backEnd.viewParms.electricFixtureKey,&triangleCount);
            if (omit) { RB_SurfaceElectricTrim((srfBspSurface_t *)ds->surface,omit,triangleCount); return; }
        }
        goto original;
    }
'''
assert s.count(oldbranch)==1
electric.write_text(s.replace(oldbranch,newbranch))

proof={
 "version":"ELSS V1.1 Component Pick",
 "base_run":42198541106,
 "base_commit":"5ba3e923803674c9acee71600412720a0eeaf81e",
 "inherits_elss_v101_persistence":True,
 "profile_read":["DW_ELSS 1","DW_ELSS 2"],
 "profile_write":"DW_ELSS 2",
 "component_pick":"edge-connected triangle island within a BSP surface",
 "architecture_guard":"component bounds + owner distance; connected wall/floor growth is rejected",
 "shadow_slot_preserved":True,
 "direct_and_localvol_preserved":True,
 "other_casters_preserved":True,
 "firevol_clean_production_preserved":True,
 "crypt1_slot6_reanchor_preserved":True,
 "map_specific_production_code":False
}
(ev/"ELSS_V11_SOURCE_PROOF.json").write_text(json.dumps(proof,indent=2)+"\n")
(ev/"ELSS_V11_SHA256.json").write_text(json.dumps({
 "tr_elss.inc":sha(elss.read_bytes()),
 "tr_electric_fixture.inc":sha(electric.read_bytes()),
 "tr_local.h":sha(local.read_bytes()),
 "tr_backend.c":sha(backend.read_bytes())
},indent=2)+"\n")
print("ELSS_V11_COMPONENT_PICK_APPLIED",proof)
